// paths on current scans: the part quota.include_snapshots adds.
func (q *Queries) RankingSnapshots(ctx context.Context) ([]RankingSnapshotsRow, error) {
	rows, err := q.db.QueryContext(ctx, rankingSnapshots)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingSnapshotsRow
	for rows.Next() {
		var i RankingSnapshotsRow
		if err := rows.Scan(&i.UserID, &i.Snapshots); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

